module sva_case(input logic clk, output logic done);
  logic [2:0] tick = 0;
  always @(posedge clk) if (tick != 3'd4) tick <= tick + 1'b1;
  function automatic [3:0] hexd(input [7:0] c);
    hexd = (c >= "A") ? 4'(c - "A" + 8'd10) :
           (c >= "0" && c <= "9") ? 4'(c - "0") : 4'h0;
  endfunction
  // position of the current sample in the rows below (the last one is held past the end)
  wire [31:0] row_idx = (tick < 3'd4) ?
                          32'(tick) : 32'd3;
  wire [55:0] ROW_a = "1 1 1 1";
  wire a = (ROW_a[8*(6-2*row_idx) +: 8] == "1");
  wire [55:0] ROW_v = "3 5 7 0";
  wire [3:0] v = 4'({hexd(ROW_v[8*(6-2*row_idx) +: 8])});
  assign done = (tick == 3'd4);
  p: assert property (@(posedge clk) a |-> $countones(v) == 2)
    $display("SVA_PASS bitcount/countones_compare sample=%0d", $sampled(tick));
    else $display("SVA_FAIL bitcount/countones_compare sample=%0d", $sampled(tick));
endmodule

module tb;
